import sys
from collections import defaultdict, deque

def find(u, parent):
    if parent[u] != u:
        parent[u] = find(parent[u], parent)
    return parent[u]

def union(u, v, parent, rank):
    rootU = find(u, parent)
    rootV = find(v, parent)
    if rootU != rootV:
        if rank[rootU] > rank[rootV]:
            parent[rootV] = rootU
        elif rank[rootU] < rank[rootV]:
            parent[rootU] = rootV
        else:
            parent[rootV] = rootU
            rank[rootU] += 1

def dfs(u, visited, parent, edges, tree_id, tree_edges):
    visited[u] = True
    for v in edges[u]:
        if not visited[v]:
            tree_edges.append((u, v))
            dfs(v, visited, parent, edges, tree_id, tree_edges)

